param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$flags=[Reflection.BindingFlags]'Public,Instance,Static,DeclaredOnly';$rows=@()
foreach($type in @([Text.Encoding],[Text.UTF8Encoding],[Text.EncoderFallback],[Text.DecoderFallback],[Text.EncoderReplacementFallback],[Text.DecoderReplacementFallback],[Text.EncoderExceptionFallback],[Text.DecoderExceptionFallback],[Text.EncoderFallbackException],[Text.DecoderFallbackException],[Text.Encoder],[Text.Decoder],[Text.EncoderFallbackBuffer],[Text.DecoderFallbackBuffer])){
 $methods=@(foreach($method in $type.GetMethods($flags)){[ordered]@{name=$method.Name;signature=$method.ToString();isStatic=$method.IsStatic;isSpecialName=$method.IsSpecialName;genericArity=$method.GetGenericArguments().Count;returnType=$method.ReturnType.ToString();parameters=@($method.GetParameters()|ForEach-Object {[ordered]@{name=$_.Name;type=$_.ParameterType.ToString();isOut=$_.IsOut}})}})
 $rows+=[ordered]@{fullName=$type.FullName;baseType=$type.BaseType.FullName;isAbstract=$type.IsAbstract;isSealed=$type.IsSealed;constructors=@($type.GetConstructors($flags)|ForEach-Object ToString);interfaces=@($type.GetInterfaces()|ForEach-Object ToString);methods=$methods;properties=@($type.GetProperties($flags)|ForEach-Object {[ordered]@{name=$_.Name;type=$_.PropertyType.ToString();getter=($_.GetMethod -and $_.GetMethod.IsPublic);setter=($_.SetMethod -and $_.SetMethod.IsPublic)}})}
}
$profiles=@()
foreach($emit in @($false,$true)){foreach($strict in @($false,$true)){
 $encoding=[Text.UTF8Encoding]::new($emit,$strict);$profiles+=[ordered]@{emitIdentifier=$emit;throwOnInvalidBytes=$strict;codePage=$encoding.CodePage;encodingName=$encoding.EncodingName;isReadOnly=$encoding.IsReadOnly;preamble=[int[]]$encoding.GetPreamble();encoderFallback=$encoding.EncoderFallback.GetType().FullName;decoderFallback=$encoding.DecoderFallback.GetType().FullName;encoderReplacement=$(if($encoding.EncoderFallback -is [Text.EncoderReplacementFallback]){$encoding.EncoderFallback.DefaultString}else{$null});decoderReplacement=$(if($encoding.DecoderFallback -is [Text.DecoderReplacementFallback]){$encoding.DecoderFallback.DefaultString}else{$null})}
}}
$default=[Text.Encoding]::UTF8
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();types=$rows;constructorProfiles=$profiles;defaultUtf8=[ordered]@{isReadOnly=$default.IsReadOnly;preamble=[int[]]$default.GetPreamble();codePage=$default.CodePage;encoderFallback=$default.EncoderFallback.GetType().FullName;decoderFallback=$default.DecoderFallback.GetType().FullName};qualification='UTF8_CONTRACT_METADATA_ONLY; IMPLEMENTATION_FALLBACK_STATEFUL_POINTER_AND_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS pinned UTF-8 contract inventory: fourteen types and four constructor profiles'
